// P2.1 precache-coverage guard (docs/Phase-002.md, in the spirit of D11's
// parity table and P1.5.1's version pin): asserts that the service worker
// generated by `vite build` precaches every file the built client ships —
// the "boots offline" guarantee rests on it, and upstream churn is a known
// risk (Phase-002.md Appendix; vite-plugin-pwa is pinned exact partly for
// this reason).
//
// It runs against build output, so it lives here (Node) rather than in
// tests/: Vitest runs inside workerd, which has no filesystem access to
// dist/ — see P2.1's Notes. Wired into `npm run build`, so CI and
// `npm run deploy` cannot ship a precache gap.
//
// Usage: npm run check:precache   (after npm run build / vite build)

import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const clientDir = path.join(projectRoot, "dist", "client");
const swPath = path.join(clientDir, "sw.js");

function fail(message: string): never {
  console.error(`precache guard: ${message}`);
  process.exit(1);
}

if (!existsSync(swPath)) {
  fail(`${path.relative(projectRoot, swPath)} not found — run \`npm run build\` first`);
}

const sw = readFileSync(swPath, "utf8");

// generateSW emits minified Workbox code:
//   precacheAndRoute([{url:"index.html",revision:"abc…"},…],{})
const entryList = sw.match(/precacheAndRoute\(\[([\s\S]*?)\]/)?.[1];
if (entryList === undefined) {
  fail("no precacheAndRoute([...]) entry list in sw.js — Workbox output format changed; update this guard");
}

const entryPattern = /\{url:(?:"([^"]+)"|'([^']+)'),revision:(?:"([^"]+)"|null)\}/g;
const precached: string[] = [];
for (const entry of entryList.matchAll(entryPattern)) {
  precached.push(entry[1] ?? entry[2] ?? "");
}
if (precached.length === 0) {
  fail("precache entry list parsed empty — update this guard's entry regex");
}

const duplicates = [...new Set(precached.filter((url, i) => precached.indexOf(url) !== i))];
if (duplicates.length > 0) {
  fail(`duplicate precache entries: ${duplicates.join(", ")}`);
}

// The SW's own files are loaded by the browser/worker update machinery,
// not by the app shell — everything else must be precached.
const isSwOwnFile = (relPath: string): boolean =>
  relPath === "sw.js" ||
  relPath === ".assetsignore" ||
  relPath === "wrangler.json" ||
  /^workbox-[\w-]+\.js$/.test(relPath);

const shipped = readdirSync(clientDir, { recursive: true, encoding: "utf8" })
  .map((entry) => entry.split(path.sep).join("/"))
  .filter((relPath) => statSync(path.join(clientDir, relPath)).isFile());

const missing = shipped.filter((file) => !isSwOwnFile(file) && !precached.includes(file));
if (missing.length > 0) {
  fail(`shipped but NOT precached (offline boot would break): ${missing.join(", ")}`);
}

const stale = precached.filter((url) => !shipped.includes(url));
if (stale.length > 0) {
  fail(`precached but NOT on disk (stale entries): ${stale.join(", ")}`);
}

console.log(`precache guard: ${precached.length} entries cover all ${shipped.length} shipped client files`);
